-- Add View/Edit actions and their popup forms to the original Sprint 2 pages.
-- Generated from NocoBase's flowSurfaces API. Existing models and records stay intact.
-- The fixed UIDs make this migration safe to run on every startup.
BEGIN;
DO $migration$
BEGIN
  IF to_regclass('public."flowModels"') IS NULL THEN
    RAISE NOTICE 'No prototype flow models found; skipping UI migration.';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM "flowModels" WHERE uid IN
      ('a8c1500a514', 'd4d5bdb8435', 'cb7955f07ea', '9a0b8179b5e')) <> 4 THEN
    RAISE NOTICE 'Original prototype tables not found; skipping UI migration.';
    RETURN;
  END IF;
  ON CONFLICT DO NOTHING;

  ON CONFLICT DO NOTHING;

  ON CONFLICT DO NOTHING;

  ON CONFLICT DO NOTHING;

END;
$migration$;
COMMIT;
